export function rng(seed){let n=seed>>>0;return()=>{n+=0x6D2B79F5;let t=n;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
export function createState(seed=Math.floor(Math.random()*2147483647)){return{version:2,campaignVersion:CAMPAIGN_VERSION,talents:createTalents(),astral:createAstral(),descent:createDescentProgress(),zag:createZag(),miner:createMiner(seed),village:createVillage(),records:createRecords(),experience:createExperience(),legacyForce:0,offerings:0,pendingBlessing:null,pendingBlessingLevel:1,pendingBlessingRoll:null,relics:[],materials:emptyMaterials(),forge:createForge(),seed,abyssBest:0,bank:30,essence:0,mission:null,extraMissions:[],missionRoll:0,missionBoard:{key:'',offers:[]},missionsCompleted:0,stars:0,starUpgrades:{supplies:0,charge:0,yield:0},level:1,core:0,seals:0,best:0,attempts:0,deaths:0,unlocked:[],equipped:[],skillRanks:{},totalGems:0,bestCombo:0,run:null,lastResult:null};}
export const maxRhythm=()=>100;
export const maxHealth=s=>Math.floor(forgeEffects(s).health*blessingEffects(s.run).health);
export const tonicHealing=s=>forgeEffects(s).tonic*(1+progressionEffects(s).potion);
