const PROC_NAMES={lucky:'DANO DUPLO',popcorn:'EXPLOSÃO',ricochet:'RICOCHETE',ember:'QUEIMANDO',ice:'INIMIGO ENFRAQUECIDO',shell:'DANO REDUZIDO',laser:'RAIO EM CRUZ',echohit:'GOLPE EXTRA',bombgift:'BOMBA EXTRA',revival:'NOVA CHANCE'};
function proc(r,id,target=r.player,label){const card=CARDS.find(c=>c.id===id);event(r,'proc',{id,name:label||PROC_NAMES[id]||card.name,color:card.color,x:target.x,y:target.y});}
function healCard(s,id,amount,target){const r=s.run;if(!cardCount(r,id)||amount<=0)return;const gained=Math.min(amount,maxHealth(s)-r.health);if(gained<=0)return;r.health+=gained;proc(r,id,target,'VIDA +'+Math.round(gained));event(r,'heal',{...r.player,value:gained});}
function cardRoll(r,id,beat,targetId){let salt=0;for(const char of id)salt=(salt*31+char.charCodeAt(0))>>>0;return rng(r.room.seed+beat*3989+targetId*97+salt)();}
function applyHitCards(s,target,beat){const r=s.run,all=()=>[...r.room.nodes,...r.room.enemies,...r.room.rocks].filter(n=>n.hp>0);
 const count=id=>cardCount(r,id),value=id=>cardValues(id,count(id),power(s)),roll=id=>count(id)>0&&cardRoll(r,id,beat,target.id)<value(id).chance;
 r.cardHits=(r.cardHits||0)+1;
 if(count('ember')&&target.hp>0){target.burn={start:beat,until:beat+3,damage:value('ember').damage*(1+progressionEffects(s).burnPower)};proc(r,'ember',target);}
 if(target.type==='enemy'&&target.hp>0&&roll('ice')){target.chill={until:beat+4,reduction:value('ice').reduction};if(!target.boss){target.stunUntil=Math.max(target.stunUntil,beat+1);target.windup=null;}proc(r,'ice',target);}
 if(roll('popcorn')){for(const n of all())if(distance(n,r.player)<=2)damageTarget(s,n,value('popcorn').damage,true);proc(r,'popcorn');event(r,'bomb',{...r.player});}
 if(count('ricochet')){const n=all().filter(n=>n!==target&&distance(n,target)<=5).sort((a,b)=>distance(a,target)-distance(b,target))[0];if(n){damageTarget(s,n,value('ricochet').damage,true);proc(r,'ricochet',n);event(r,'echo',{from:target,x:n.x,y:n.y});}}
 if(roll('laser')){for(const n of all())if((n.x===r.player.x||n.y===r.player.y)&&distance(n,r.player)<=5)damageTarget(s,n,value('laser').damage,true);proc(r,'laser');event(r,'wave',{...r.player,color:P.yellow});}
 if(target.hp>0&&roll('echohit')){damageTarget(s,target,value('echohit').damage,true);proc(r,'echohit',target);}
}
function applyRunCard(s,id){const r=s.run,c=CARDS.find(c=>c.id===id);if(!r||!c||cardCount(r,id)>=cardLimit(c,s))return false;r.cards??={};r.cards[id]=cardCount(r,id)+1;progressionEffects(s);reveal(r.room,r.player,sightRange(r));event(r,'card',{id});return true;}
export function chooseCard(s,id){const r=s.run;if(!r||isAbyss(r)||!r.room.cleared||r.cardChosen||!r.cardOffer?.includes(id))return false;if(!applyRunCard(s,id))return false;r.cardChosen=true;return true;}
export function chooseAbyssCard(s,id,automatic=false){
 const r=s.run,c=r?.abyss?.cardChoice;if(!isAbyss(r)||!c||!c.offers.includes(id)||!abyssCardDefinition(id))return false;
 if(automatic?c.remaining!==0||id!==c.offers[c.autoIndex]:c.remaining<=0)return false;
 if(id==='abyss-heal')r.health=Math.min(maxHealth(s),r.health+25);
 else if(id==='abyss-breath')r.rhythm=Math.min(maxRhythm(s),r.rhythm+30);
 else if(id==='abyss-ward')r.guardUntil=Math.max(r.guardUntil,Math.max(r.beat,r.acted)+8);
 else if(!applyRunCard(s,id))return false;
 r.abyss.cardChoice=null;event(r,'abyssCardChosen',{id,automatic});return true;
}
export function advanceAbyssCards(s,seconds){const id=advanceAbyssChoice(s.run,seconds);return id&&chooseAbyssCard(s,id,true)?id:null;}
export function floorRewards(s){const r=s.run,from=r?.room.floorStart;if(!r||!from)return null;return{gems:Math.max(0,r.bag-from.bag),points:Math.max(0,(r.score?.points||0)-from.points),stars:Math.max(0,(r.score?.earned||0)-from.stars),essence:Math.max(0,(r.loot?.essence||0)-from.essence)};}
